import java.util.*;
public class User { private final int id; private final String name; private final Profile profile=new Profile(); private final List<User> connections=new ArrayList<>(); private final List<Message> messages=new ArrayList<>(); private final List<Notification> notifications=new ArrayList<>(); public User(int id,String name){this.id=id;this.name=name;} public int getId(){return id;} public String getName(){return name;} public Profile getProfile(){return profile;} public List<User> getConnections(){return connections;} public List<Message> getMessages(){return messages;} public List<Notification> getNotifications(){return notifications;} public void addSkill(Skill s){profile.addSkill(s);} public void addEducation(Education e){profile.addEducation(e);} public void addExperience(Experience e){profile.addExperience(e);} public void addConnection(User u){if(!connections.contains(u))connections.add(u);} public boolean isConnectedTo(User u){return connections.contains(u);} public void addMessage(Message m){messages.add(m);} public void addNotification(Notification n){notifications.add(n);} public void displayNotifications(){for(Notification n:notifications)System.out.println(n.getMessage());} public void displayMessages(){for(Message m:messages)System.out.println(m.getSender().getName()+": "+m.getContent());} }
